-- قيد: المخطط الكامل (نسخة مجمّعة من migrations/ بالترتيب).
-- لا تحتاجه في التشغيل العادي: الهجرات تُطبَّق تلقائيًا. هذا للاستعادة اليدوية فقط:
--   psql "$DATABASE_URL" -f database/schema.sql

-- ===== migrations/0001_auth.sql =====
-- Better Auth schema (identity + sessions for "Sign in with Grok").
--
-- Generated by the Better Auth CLI for its Postgres adapter — DO NOT EDIT by
-- hand. `@/lib/auth/server` runs Better Auth against these tables when
-- DATABASE_URL is set. The columns are camelCase and MUST stay double-quoted so
-- Postgres preserves the case Better Auth queries by.
--
-- Migrations in this folder are the single source of truth for your schema. They
-- apply to Neon during the Vercel build (`npm run build`) and to the local
-- PGLite fallback automatically on startup, so dev matches production. Applied
-- files are recorded by name in `_migrations` and NEVER run again.
--
-- Put YOUR app's schema in NEW ordered files (0002_*.sql, 0003_*.sql, …), never
-- in this one. For app tables, prefer snake_case and give per-user tables a
-- `user_id TEXT NOT NULL` column (TEXT, not UUID — the preview dev user id is
-- the string 'dev-user'), then scope every query to the authenticated user
-- server-side (see the `neon` + `auth` skills and src/lib/auth/verify.server.ts).

create table if not exists "user" (
  "id" text not null primary key,
  "name" text not null,
  "email" text not null unique,
  "emailVerified" boolean not null,
  "image" text,
  "createdAt" timestamptz default CURRENT_TIMESTAMP not null,
  "updatedAt" timestamptz default CURRENT_TIMESTAMP not null
);

create table if not exists "session" (
  "id" text not null primary key,
  "expiresAt" timestamptz not null,
  "token" text not null unique,
  "createdAt" timestamptz default CURRENT_TIMESTAMP not null,
  "updatedAt" timestamptz not null,
  "ipAddress" text,
  "userAgent" text,
  "userId" text not null references "user" ("id") on delete cascade
);

create table if not exists "account" (
  "id" text not null primary key,
  "accountId" text not null,
  "providerId" text not null,
  "userId" text not null references "user" ("id") on delete cascade,
  "accessToken" text,
  "refreshToken" text,
  "idToken" text,
  "accessTokenExpiresAt" timestamptz,
  "refreshTokenExpiresAt" timestamptz,
  "scope" text,
  "password" text,
  "createdAt" timestamptz default CURRENT_TIMESTAMP not null,
  "updatedAt" timestamptz not null
);

create table if not exists "verification" (
  "id" text not null primary key,
  "identifier" text not null,
  "value" text not null,
  "expiresAt" timestamptz not null,
  "createdAt" timestamptz default CURRENT_TIMESTAMP not null,
  "updatedAt" timestamptz default CURRENT_TIMESTAMP not null
);

create index if not exists "session_userId_idx" on "session" ("userId");
create index if not exists "account_userId_idx" on "account" ("userId");
create index if not exists "verification_identifier_idx" on "verification" ("identifier");

-- ===== migrations/0002_qayd.sql =====
-- Accounts progress + online tables for قيد.
create table if not exists qayd_profiles (
  user_id text primary key,
  display_name text not null default '',
  data jsonb not null default '{}'::jsonb,
  updated_at bigint not null
);

create table if not exists qayd_rooms (
  code text primary key,
  title text not null,
  host_id text,
  phase text not null default 'lobby',
  updated_at bigint not null
);

create table if not exists qayd_members (
  code text not null references qayd_rooms(code) on delete cascade,
  user_id text not null,
  seat integer,
  name text not null,
  last_seen bigint not null,
  primary key (code, user_id)
);

create unique index if not exists qayd_members_seat_idx
  on qayd_members (code, seat)
  where seat is not null;

create table if not exists qayd_mail (
  id bigserial primary key,
  code text not null,
  to_user text,
  from_user text not null,
  kind text not null,
  body jsonb not null default '{}'::jsonb,
  at bigint not null
);

create index if not exists qayd_mail_code_id_idx on qayd_mail (code, id);

-- ===== migrations/0003_qayd_match.sql =====
-- One id per live hand, cleared when the hand ends or the host leaves.
alter table qayd_rooms add column if not exists match_id text;

-- ===== migrations/0004_qayd_xp.sql =====
-- Server-owned XP. The client may display it, but only settle writes the total.
alter table qayd_profiles add column if not exists xp_total integer;

update qayd_profiles
set xp_total = case
  when coalesce(data->'rank'->>'total', '') ~ '^[0-9]+$' then (data->'rank'->>'total')::int
  else 0
end
where xp_total is null;

create table if not exists qayd_xp_log (
  user_id text not null,
  match_id text not null,
  kind text not null,
  base_xp integer not null,
  eval_xp integer not null,
  cheat_xp integer not null,
  net_xp integer not null,
  total_before integer not null,
  total_after integer not null,
  level_after integer not null,
  at bigint not null,
  primary key (user_id, match_id)
);

-- ===== migrations/0005_qayd_friends.sql =====
-- Friend graph keyed by the stable account id. Presence is last_seen, not a fake flag.
alter table qayd_profiles add column if not exists last_seen bigint;

create table if not exists qayd_friends (
  from_id text not null,
  to_id text not null,
  status text not null,
  created_at bigint not null,
  primary key (from_id, to_id)
);

create index if not exists qayd_friends_to_idx on qayd_friends (to_id, status);

-- ===== migrations/0006_qayd_matches_invites.sql =====
-- Server-side match register: XP only counts for a match the server saw start.
create table if not exists qayd_matches (
  match_id text primary key,
  kind text not null,
  owner_id text not null,
  code text,
  started_at bigint not null,
  ended_at bigint,
  winner integer
);

create index if not exists qayd_matches_owner_idx on qayd_matches (owner_id, started_at);

create table if not exists qayd_match_seats (
  match_id text not null,
  user_id text not null,
  seat integer not null,
  primary key (match_id, user_id)
);

-- Real friend invitations (the old button only opened a room for the sender).
create table if not exists qayd_invites (
  from_id text not null,
  to_id text not null,
  code text not null,
  at bigint not null,
  primary key (from_id, to_id)
);

create index if not exists qayd_invites_to_idx on qayd_invites (to_id, at);
create index if not exists qayd_xp_log_user_at_idx on qayd_xp_log (user_id, at);
create index if not exists qayd_members_user_idx on qayd_members (user_id);

-- ===== migrations/0007_qayd_room_settings.sql =====
-- Session settings chosen by the table owner: play mode, match length, stake.
alter table qayd_rooms add column if not exists settings jsonb not null default '{}'::jsonb;

-- ===== migrations/0008_qayd_notifications.sql =====
-- Per-account notices. A normal player can only read and change their own rows.
create table if not exists qayd_notifications (
  id bigserial primary key,
  user_id text not null,
  kind text not null,
  title text not null,
  body text not null default '',
  href text not null default '',
  dedupe text not null,
  read_at bigint,
  created_at bigint not null
);

create unique index if not exists qayd_notifications_dedupe_idx
  on qayd_notifications (user_id, dedupe);

create index if not exists qayd_notifications_user_idx
  on qayd_notifications (user_id, created_at desc);

-- ===== migrations/0009_qayd_eval.sql =====
alter table qayd_matches add column if not exists eval jsonb;

-- ===== migrations/0010_qayd_cuts.sql =====
alter table qayd_matches add column if not exists cuts jsonb;


